arguments.file_text:
@page "/apply"
@using sv_2ae97650fd13465aae792d16d8c90da1.Models
@using sv_2ae97650fd13465aae792d16d8c90da1.Services
@inject IApplicationService ApplicationService
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="apply-container">
    <h1>Job Application</h1>

    @* Step Indicator Bar *@
    <nav class="step-indicator">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var stepIndex = i;
            var stepClass = GetStepClass(stepIndex);
            <div class="step @stepClass" @onclick="() => NavigateToStep(stepIndex)">
                <div class="step-circle">
                    @if (IsStepCompleted(stepIndex))
                    {
                        <span class="checkmark">&#10003;</span>
                    }
                    else
                    {
                        <span>@(stepIndex + 1)</span>
                    }
                </div>
                <span class="step-label">@StepNames[stepIndex]</span>
            </div>
            @if (stepIndex < StepNames.Length - 1)
            {
                <div class="step-connector @(IsStepCompleted(stepIndex) ? "completed" : "")"></div>
            }
        }
    </nav>

    @if (!string.IsNullOrEmpty(errorMessage))
    {
        <div class="error-banner">@errorMessage</div>
    }

    @* Step Content *@
    <div class="step-content">
        @switch (currentStep)
        {
            case 0:
                @RenderPersonalInfo();
                break;
            case 1:
                @RenderWorkHistory();
                break;
            case 2:
                @RenderReferences();
                break;
            case 3:
                @RenderCoverLetter();
                break;
            case 4:
                @RenderReviewSubmit();
                break;
        }
    </div>
</div>

@* Step 1: Personal Info *@
@{
    RenderFragment RenderPersonalInfo() => __builder =>
    {
        <h2>Personal Information</h2>
        <div class="form-group">
            <label for="fullName">Full Name *</label>
            <input id="fullName" type="text" @bind="fullName" @bind:event="oninput" placeholder="Enter your full name" />
        </div>
        <div class="form-group">
            <label for="email">Email *</label>
            <input id="email" type="email" @bind="email" @bind:event="oninput" placeholder="Enter your email" />
        </div>
        <div class="form-group">
            <label for="phone">Phone *</label>
            <input id="phone" type="tel" @bind="phone" @bind:event="oninput" placeholder="Enter your phone number" />
        </div>
        <div class="form-group">
            <label for="address">Address *</label>
            <input id="address" type="text" @bind="address" @bind:event="oninput" placeholder="Enter your address" />
        </div>
        <div class="button-group">
            <button class="btn-next" @onclick="NextFromPersonalInfo" disabled="@isProcessing">
                @if (isProcessing)
                {
                    <span>Validating...</span>
                }
                else
                {
                    <span>Next</span>
                }
            </button>
        </div>
    };
}

@* Step 2: Work History *@
@{
    RenderFragment RenderWorkHistory() => __builder =>
    {
        <h2>Work History</h2>
        @for (int i = 0; i < workEntries.Count; i++)
        {
            var index = i;
            <div class="work-entry-card">
                <div class="work-entry-header">
                    <h3>Position @(index + 1)</h3>
                    @if (workEntries.Count > 1)
                    {
                        <button class="btn-remove" @onclick="() => RemoveWorkEntry(index)">Remove</button>
                    }
                </div>
                <div class="form-group">
                    <label>Company Name *</label>
                    <input type="text" value="@workEntries[index].Company" @onchange="(e) => UpdateWorkEntry(index, company: e.Value?.ToString())" />
                </div>
                <div class="form-group">
                    <label>Job Title *</label>
                    <input type="text" value="@workEntries[index].Title" @onchange="(e) => UpdateWorkEntry(index, title: e.Value?.ToString())" />
                </div>
                <div class="form-row">
                    <div class="form-group">
                        <label>Start Date *</label>
                        <input type="date" value="@workEntries[index].StartDate.ToString("yyyy-MM-dd")" @onchange="(e) => UpdateWorkEntryStartDate(index, e.Value?.ToString())" />
                    </div>
                    <div class="form-group">
                        <label>End Date</label>
                        <input type="date" value="@(workEntries[index].EndDate?.ToString("yyyy-MM-dd"))" @onchange="(e) => UpdateWorkEntryEndDate(index, e.Value?.ToString())" disabled="@workEntries[index].IsCurrent" />
                    </div>
                </div>
                <div class="form-group checkbox-group">
                    <input type="checkbox" id="current-@index" checked="@workEntries[index].IsCurrent" @onchange="(e) => ToggleCurrentJob(index, (bool)(e.Value ?? false))" />
                    <label for="current-@index">I currently work here</label>
                </div>
                <div class="form-group">
                    <label>Description</label>
                    <textarea rows="3" value="@workEntries[index].Description" @onchange="(e) => UpdateWorkEntry(index, description: e.Value?.ToString())"></textarea>
                </div>
            </div>
        }
        <button class="btn-add" @onclick="AddWorkEntry">+ Add Another Position</button>
        <div class="button-group">
            <button class="btn-back" @onclick="PreviousStep">Back</button>
            <button class="btn-next" @onclick="NextFromWorkHistory">Next</button>
        </div>
    };
}

@* Step 3: References *@
@{
    RenderFragment RenderReferences() => __builder =>
    {
        <h2>References</h2>
        @for (int i = 0; i < references.Count; i++)
        {
            var index = i;
            <div class="reference-card">
                <div class="work-entry-header">
                    <h3>Reference @(index + 1)</h3>
                    @if (references.Count > 2)
                    {
                        <button class="btn-remove" @onclick="() => RemoveReference(index)">Remove</button>
                    }
                </div>
                <div class="form-group">
                    <label>Name *</label>
                    <input type="text" value="@references[index].Name" @onchange="(e) => UpdateReference(index, name: e.Value?.ToString())" />
                </div>
                <div class="form-group">
                    <label>Relationship *</label>
                    <input type="text" value="@references[index].Relationship" @onchange="(e) => UpdateReference(index, relationship: e.Value?.ToString())" />
                </div>
                <div class="form-group">
                    <label>Email *</label>
                    <input type="email" value="@references[index].Email" @onchange="(e) => UpdateReference(index, email: e.Value?.ToString())" />
                </div>
                <div class="form-group">
                    <label>Phone *</label>
                    <input type="text" value="@references[index].Phone" @onchange="(e) => UpdateReference(index, phone: e.Value?.ToString())" />
                </div>
            </div>
        }
        @if (references.Count < 3)
        {
            <button class="btn-add" @onclick="AddReference">+ Add Reference</button>
        }
        <div class="button-group">
            <button class="btn-back" @onclick="PreviousStep">Back</button>
            <button class="btn-next" @onclick="NextFromReferences">Next</button>
        </div>
    };
}

@* Step 4: Cover Letter *@
@{
    RenderFragment RenderCoverLetter() => __builder =>
    {
        <h2>Cover Letter</h2>
        <div class="form-group">
            <textarea id="coverLetter" rows="12" maxlength="2000" @bind="coverLetter" @bind:event="oninput" placeholder="Write your cover letter here..."></textarea>
            <div class="char-count">@(coverLetter?.Length ?? 0) / 2000 characters</div>
        </div>
        <div class="button-group">
            <button class="btn-back" @onclick="PreviousStep">Back</button>
            <button class="btn-next" @onclick="NextFromCoverLetter">Next</button>
        </div>
    };
}

@* Step 5: Review & Submit *@
@{
    RenderFragment RenderReviewSubmit() => __builder =>
    {
        if (isSubmitted)
        {
            <div class="confirmation">
                <div class="confirmation-icon">&#10003;</div>
                <h2>Application Submitted!</h2>
                <p>Your application has been successfully submitted.</p>
                <p class="application-id">Application ID: <strong>@submittedApplicationId</strong></p>
            </div>
        }
        else
        {
            <h2>Review & Submit</h2>

            <div class="review-section">
                <div class="review-header">
                    <h3>Personal Information</h3>
                    <a class="edit-link" @onclick='() => GoToStep(0)'>Edit</a>
                </div>
                <dl class="review-data">
                    <dt>Full Name</dt><dd>@fullName</dd>
                    <dt>Email</dt><dd>@email</dd>
                    <dt>Phone</dt><dd>@phone</dd>
                    <dt>Address</dt><dd>@address</dd>
                </dl>
            </div>

            <div class="review-section">
                <div class="review-header">
                    <h3>Work History</h3>
                    <a class="edit-link" @onclick='() => GoToStep(1)'>Edit</a>
                </div>
                @foreach (var entry in workEntries)
                {
                    <div class="review-work-entry">
                        <strong>@entry.Title</strong> at <strong>@entry.Company</strong>
                        <div>@entry.StartDate.ToString("MMM yyyy") &ndash; @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))</div>
