    padding-bottom: 1rem;
    margin-bottom: 1rem;
}

.review-section:last-of-type {
    border-bottom: none;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.review-header h3 {
    margin: 0 0 0.5rem 0;
}

.edit-link {
    color: #0d6efd;
    cursor: pointer;
    font-size: 0.9rem;
    text-decoration: underline;
}

.edit-link:hover {
    color: #0a58ca;
}

.review-data {
    display: grid;
