}

.review-data dd {
    margin: 0;
}

.review-work-entry,
.review-reference {
    margin-bottom: 0.75rem;
    padding: 0.5rem 0;
}

.review-cover-letter {
    white-space: pre-wrap;
    background: #f8f9fa;
    padding: 1rem;
    border-radius: 4px;
}

