    background: #198754;
    color: #fff;
    font-size: 2rem;
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0 auto 1rem;
}

.application-id {
    font-size: 1.1rem;
    margin-top: 1rem;
}

